/**
 * Hand-written: the generator asserts no width, and the 440px panel beside the
 * run is the series screen's frame (Work-Screen; the same frame as
 * src/routes/series/[id]/+page.svelte). This is the number that makes the
 * screen the series screen rather than a wide page.
 */
test("The Work screen: the panel is the series screen's 440px", async ({ page }) => {
	await page.goto(`${base}/work/${workId}`);
	const width = await page
		.locator('.panel')
		.evaluate((node) => Math.round(node.getBoundingClientRect().width));
	expect(width).toBe(440);
	// The run sits beside it, not under it, once there is room.
	await expect(page.locator('.work > .body')).toHaveCSS('flex-direction', 'row');
});
